[resource]
name = "${i}"
scope = "${n}"
timestamps = true

[admin]
visible = false

[permissions]
list   = "${r}"
read   = "${r}"
create = "private"
update = "private"
delete = "${r}"

[fields.owner_id]
type = "reference"
references = "user"
required = true
on_delete = "cascade"

[fields.title]
type = "string"
max_length = 200

[fields.summary]
type = "text"
hidden = true

[fields.summary_message_count]
type = "integer"
hidden = true

[fields.summary_characters]
type = "integer"
hidden = true

[fields.summary_updated_at]
type = "timestamp"
hidden = true
